<?php
namespace App\Modules\Orders\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Customers\Domain\Models\CustomerProfile;use App\Modules\Orders\Domain\Enums\OrderPriority;use App\Modules\Pricing\Domain\Models\PriceList;use Illuminate\Http\Request;use Inertia\Inertia;use Inertia\Response;
class CreateSalesOrderController extends Controller {public function __invoke(Request $request):Response{abort_unless($request->user()->hasPermission('orders.manage'),403);return Inertia::render('orders/Create',$this->props()+['now'=>now()->format('Y-m-d\TH:i'),'due'=>now()->addDay()->format('Y-m-d\TH:i')]);}public function props():array{return ['customers'=>CustomerProfile::query()->with('person:id,name')->where('is_active',true)->orderBy('created_at')->get()->map(fn($c)=>['id'=>$c->id,'name'=>$c->person->name,'default_price_list_id'=>$c->default_price_list_id]),'priceLists'=>PriceList::query()->with(['items.presentation.item:id,name'])->where('is_active',true)->get()->map(fn($l)=>['id'=>$l->id,'name'=>$l->name,'is_default'=>$l->is_default,'items'=>$l->items->map(fn($i)=>['id'=>$i->id,'presentation_id'=>$i->presentation_id,'product'=>"{$i->presentation->item->name} — {$i->presentation->name}",'price'=>$i->price,'minimum_price'=>$i->minimum_price])]),'priorities'=>collect(OrderPriority::cases())->map(fn($p)=>['value'=>$p->value,'label'=>$p->label()])];}}
